INSERT INTO `HealthIndicators` VALUES (1,'110600','110600:HEALTH - HHC (Category)','','',71,24),(2,'2.4_OOSC.RATE','Rate of out of school children, national source (% of relevant age group) ','Number of children of official primary school age who are not enrolled in primary or secondary school, expressed as a percentage of the population of official primary school age. This indicator is intended to measure the size of the population in the official primary school age range that should be targeted by policies and efforts to achieve universal primary education. Country-specific definition, method and targets are determined by countries themselves. ','',34,24),(3,'3.13_PRI.MATH.BOOK.PER.PUPIL','Ratio of textbooks per pupil, primary education, mathematics','Number of books used by a single pupil used as a standard work for the study of the mathematics subject. Country-specific definition, method and targets are determined by countries themselves. ','',34,24),(4,'3.14_PRI.LANGU.BOOK.PER.PUPIL','Ratio of textbooks per pupil, primary education, language','Number of books used by a single pupil used as a standard work for the study of the primary language of instruction. Country-specific definition, method and targets are determined by countries themselves. ','',34,24),(5,'5.2.1_TLS.TOT.AID.AUSAID.CFAUS',' International aid disbursed to total education, AusAID and ChildFund Australia to Tajikistan (USD million)  ','International concessional aid disbursed by the reporting development partner to the total education sector in the specific developing country. Targets indicate scheduled or projected aid. Accounted aid includes activities, projects, technical cooperation and sector and budget support (20%), as it was reported by the donor to the Global Partnership for Education.','',34,24),(6,'5.2.8_TLS.TOT.AID.CFNZL',' International aid disbursed to total education, ChildFund NZAID and UNICEF to Timor-Leste (USD million)  ','International concessional aid disbursed by the reporting development partner to the total education sector in the specific developing country. Targets indicate scheduled or projected aid. Accounted aid includes activities, projects, technical cooperation and sector and budget support (20%), as it was reported by the donor to the Global Partnership for Education.','',34,24),(7,'9080000','9080000:ACTUAL HEALTH','','',78,24),(8,'BI.EMP.FRML.HE.PB.ZS','Health workers, as a share of public formal employees','','',64,24),(9,'BI.EMP.FRML.PB.HE.ZS','Public sector employment, as a share of formal employment, by industry: Health','','',64,24),(10,'BI.EMP.PUBS.FE.HE.ZS','Public sector female employment, as a share of paid employment by industry: Health','','',64,24),(11,'BI.EMP.PWRK.HE.PB.ZS','Health workers, as a share of public paid employees','','',64,24),(12,'BI.EMP.PWRK.PB.HE.ZS','Public sector employment, as a share of paid employment, by industry: Health','','',64,24),(13,'BI.EMP.TOTL.HE.PB.ZS','Health workers, as a share of public total employees','','',64,24),(14,'BI.EMP.TOTL.NO.HE','Number of employed employees, by industry: Health','','',64,24),(15,'BI.EMP.TOTL.PB.HE.ZS','Public sector employment, as a share of total employment, by industry: Health','','',64,24),(16,'BI.PWK.AGES.PB.HE.MD','Median age of public paid employees, by industry: Health','','',64,24),(17,'BI.PWK.AGES.PB.HE.SM','Mean age of public paid employees, by industry: Health','','',64,24),(18,'BI.PWK.AGES.PV.HE.MD','Median age of private paid employees, by industry: Health','','',64,24),(19,'BI.PWK.AGES.PV.HE.SM','Mean age of private paid employees, by industry: Health','','',64,24),(20,'BI.PWK.CMPA.HD.MD','Cross-country public sector pay comparison ratio, by occupation: Hospital doctor (using median)','','',64,24),(21,'BI.PWK.CMPA.HD.SM','Cross-country public sector pay comparison ratio, by occupation: Hospital doctor (using mean)','','',64,24),(22,'BI.PWK.CMPA.HN.MD','Cross-country public sector pay comparison ratio, by occupation: Hospital nurse (using median)','','',64,24),(23,'BI.PWK.CMPA.HN.SM','Cross-country public sector pay comparison ratio, by occupation: Hospital nurse (using mean)','','',64,24),(24,'BI.PWK.PRVS.HS.ZS','Share of private paid employees with health insurance','','',64,24),(25,'BI.PWK.PRVS.TT.HE.ZS','Individuals with tertiary education as a share of private paid employees, by industry: Health','','',64,24),(26,'BI.PWK.PUBS.HE.FE.ZS','Females, as a share of public paid employees by industry: Health','','',64,24),(27,'BI.PWK.PUBS.HS.ZS','Share of public paid employees with health insurance','','',64,24),(28,'BI.PWK.PUBS.NO.HE','Number of public paid employees, by industry: Health','','',64,24),(29,'BI.PWK.PUBS.RU.HE.ZS','Rural residents, as a share of public paid employees, by industry: Health','','',64,24),(30,'BI.PWK.PUBS.TT.HE.ZS','Individuals with tertiary education as a share of public paid employees, by industry: Health','','',64,24),(31,'BI.PWK.TOTL.NO.HE','Number of paid employees, by industry: Health','','',64,24),(32,'BI.WAG.CPRS.PB.HD.ZS','Pay compression ratio in public sector, by occupation: Hospital doctor (clerk as reference)','','',64,24),(33,'BI.WAG.CPRS.PB.HN.ZS','Pay compression ratio in public sector, by occupation: Hospital nurse (clerk as reference)','','',64,24),(34,'BI.WAG.PREM.FE.HE','Public sector wage premium for females, by industry: Health (compared to paid wage employees)','','',64,24),(35,'BI.WAG.PREM.HE','Public sector wage premium, by industry: Health (compared to formal wage employees)','','',64,24),(36,'BI.WAG.PREM.HE.GP','Public sector wage premium, by industry: Health (compared to all private employees)','','',64,24),(37,'BI.WAG.PREM.MA.HE','Public sector wage premium for males, by industry: Health (compared to paid wage employees)','','',64,24),(38,'BI.WAG.PREM.PB.FE.HE','P-Value: Public sector wage premium for females, by industry: Health (compared to paid wage employees)','','',64,24),(39,'BI.WAG.PREM.PB.FM.HE','P-Value: Gender wage premium in the public sector, by industry: Health (compared to male paid employees)','','',64,24),(40,'BI.WAG.PREM.PB.HE.PE','P-Value: Public sector wage premium, by industry: Health (compared to all private employees)','','',64,24),(41,'BI.WAG.PREM.PB.HE.WE','P-Value: Public sector wage premium, by industry: Health (compared to formal wage employees)','','',64,24),(42,'BI.WAG.PREM.PB.MA.HE','P-Value: Public sector wage premium for males, by industry: Health (compared to paid wage employees)','','',64,24),(43,'BI.WAG.PREM.PV.FM.HE','P-Value: Gender wage premium in the private sector, by industry: Health (compared to male paid employees)','','',64,24),(44,'BI.WAG.PRVS.HE.FM','Gender wage premium in the private sector, by industry: Health (compared to male paid employees)','','',64,24),(45,'BI.WAG.PUBS.HE.FM','Gender wage premium in the public sector, by industry: Health (compared to male paid employees)','','',64,24),(46,'birth_reg','Children under age 5 whose births are registered, total (%)','Percentage of children under age 5 who were registered at the moment of the survey. The numerator of this indicator includes children reported to have a birth certificate, regardless of whether or not it was seen by the interviewer, and those without a birth certificate whose mother or caregiver says the birth has been registered, total.','',89,24),(47,'birth_reg_1','Children under age 5 whose births are registered, female (%)','Percentage of children under age 5 who were registered at the moment of the survey. The numerator of this indicator includes children reported to have a birth certificate, regardless of whether or not it was seen by the interviewer, and those without a birth certificate whose mother or caregiver says the birth has been registered, women.','',89,24),(48,'birth_reg_2','Children under age 5 whose births are registered, male (%)','Percentage of children under age 5 who were registered at the moment of the survey. The numerator of this indicator includes children reported to have a birth certificate, regardless of whether or not it was seen by the interviewer, and those without a birth certificate whose mother or caregiver says the birth has been registered, men.','',89,24),(49,'CC.AVPB.PTPI.HE','Additional people below $1.90 as % of total population by impact - Health','Additional people below $1.90 as % of total population by impact, from climate change impacts relating to Health, is generated from data within Shock Waves : Managing the Impacts of Climate Change on Poverty. This report examines the potential impact of climate change and climate policies on poverty reduction. It also provides guidance on how to create a “win-win” situation so that climate change policies contribute to poverty reduction and poverty-reduction policies contribute to climate change mitigation and resilience building. The key finding of the report is that climate change represents a significant obstacle to the sustained eradication of poverty, but future impacts on poverty are determined by policy choices: rapid, inclusive, and climate-informed development can prevent most short-term impacts whereas immediate pro-poor, emissions-reduction policies can drastically limit long-term ones.','',87,24),(50,'CC.AVPB.TPOP.HE','Additional people below $4 as % of total population by impact, by 2030 - Health','Additional people below $4 as % of total population by impact, by 2030, from climate change impacts relating to Health, is generated from data within Shock Waves : Managing the Impacts of Climate Change on Poverty. This report examines the potential impact of climate change and climate policies on poverty reduction. It also provides guidance on how to create a “win-win” situation so that climate change policies contribute to poverty reduction and poverty-reduction policies contribute to climate change mitigation and resilience building. The key finding of the report is that climate change represents a significant obstacle to the sustained eradication of poverty, but future impacts on poverty are determined by policy choices: rapid, inclusive, and climate-informed development can prevent most short-term impacts whereas immediate pro-poor, emissions-reduction policies can drastically limit long-term ones.','',87,24),(51,'CC.CHIC.BTFP.HE','Change in income (%) for bottom 40% of the population by impact, by 2030 - Health (original)','Change in income (%) for bottom 40% of the population by impact, by 2030, from climate change impacts relating to Health, is generated from data within Shock Waves : Managing the Impacts of Climate Change on Poverty. This report examines the potential impact of climate change and climate policies on poverty reduction. It also provides guidance on how to create a “win-win” situation so that climate change policies contribute to poverty reduction and poverty-reduction policies contribute to climate change mitigation and resilience building. The key finding of the report is that climate change represents a significant obstacle to the sustained eradication of poverty, but future impacts on poverty are determined by policy choices: rapid, inclusive, and climate-informed development can prevent most short-term impacts whereas immediate pro-poor, emissions-reduction policies can drastically limit long-term ones.','',87,24),(52,'CC.CHIC.CFPI.HE','Change in income (%) for bottom 40% of the population by impact - Health (update)','','',87,24),(53,'CC.CUF.STUN','Children under 5 years of age who are stunted (% of total)','Children under 5 years of age who are stunted reflects modelled estimate from the Suite of Food Security Indicators on FAOSTAT. Suite of Food Security Indicators presents the core set of food security indicators. Following the recommendation of experts gathered in the Committee on World Food Security (CFS) Round Table on hunger measurement, hosted at FAO headquarters in September 2011, an initial set of indicators aiming to capture various aspects of food insecurity is presented on FAOSTAT. The choice of the indicators has been informed by expert judgment and the availability of data with sufficient coverage to enable comparisons across regions and over time. Many of these indicators are produced and published elsewhere by FAO and other international organizations. They are reported on FAOSTAT in a single database with the aim of building a wide food security information system. More indicators will be added to this set as more data will become available. Indicators are classified along the four dimensions of food security -- availability, access, utilization and stability. This work is made available under the Creative Commons Attribution-NonCommercial-ShareAlike 3.0 IGO license (CC BY-NC-SA 3.0 IGO; https://creativecommons.org/licenses/by-nc-sa/3.0/igo). In addition to this license, some database specific terms of use are listed: Terms of Use of Datasets.','',87,24),(54,'CC.SH.AIRP.AIR','Mortality rate attributable to household air pollution (deaths per 100 000 population)','This indicator presents the mortality rate attributable to household air pollution as a factor of deaths per 100 000 population. Data is taken from the United Nations Sustainable Goals, representing Indicator 3.9.1: Crude death rate attributed to ambient air pollution (deaths per 100 000 population).','',87,24),(55,'CC.SH.AIRP.AMB','Mortality rate attributable to ambient air pollution (deaths per 100 000 population)','This indicator presents the mortality rate attributable to ambient air pollution as a factor of deaths per 100 000 population. Data is taken from the United Nations Sustainable Goals, representing Indicator 3.9.1: Crude death rate attributed to household air pollution (deaths per 100 000 population).','',87,24),(56,'CC.TCFD.COMP.HC','Number of companies that are TCFD compliant by sector - Health Care','TCFD compliant company data is sourced from the Task Force on Climate-Related Financial Disclosures and aggregated into sector brackets. The Task Force on Climate-related Financial Disclosures (TCFD) provides a framework for companies and other organizations to develop more effective climate related financial disclosures through their existing reporting processes.','',87,24),(57,'CoHD_asf_prop','Cost share for animal-sourced foods in a least-cost healthy diet','','',88,24),(58,'CoHD_asf_ss','Cost of animal-sourced foods relative to the starchy staples in a least-cost healthy diet','','',88,24),(59,'CoHD_CoCA','Cost of a healthy diet relative to the cost of sufficient energy from starchy staples','','',88,24),(60,'CoHD_f_prop','Cost share for fruits in a least-cost healthy diet','','',93,24),(61,'CoHD_f_ss','Cost of fruits relative to the starchy staples in a least-cost healthy diet','','',93,24),(62,'CoHD_fexp','Affordability of a healthy diet: ratio of cost to food expenditures','','',93,24),(63,'CoHD_headcount','Percent of the population who cannot afford a healthy diet','','',88,24),(64,'CoHD_LCU','Cost of a healthy diet in local currency unit','','',93,24),(65,'CoHD_lns_prop','Cost share for legumes, nuts and seeds in a least-cost healthy diet','','',93,24),(66,'CoHD_lns_ss','Cost of legumes, nuts and seeds relative to the starchy staples in a least-cost healthy diet','','',88,24),(67,'CoHD_of_prop','Cost share for oils and fats in a least-cost healthy diet','','',88,24),(68,'CoHD_of_ss','Cost of oils and fats relative to the starchy staples in a least-cost healthy diet','','',93,24),(69,'CoHD_pov','Affordability of a healthy diet: ratio of cost to the food poverty line','','',93,24),(70,'CoHD_PPP','Cost of a healthy diet in PPP dollars','','',93,24),(71,'CoHD_ss_prop','Cost share for starchy staples in a least-cost healthy diet','','',93,24),(72,'CoHD_unafford_n','Millions of people who cannot afford a healthy diet','','',93,24),(73,'CoHD_v_prop','Cost share for vegetables in a least-cost healthy diet','','',88,24),(74,'CoHD_v_ss','Cost of vegetables relative to the starchy staples in a least-cost healthy diet','','',88,24),(75,'DAK.HE.BSRV.CR','Total Specific Allocation Grant for Health Sector (Subsect: Basic Services) (in IDR Billion)','The Specific Allocation Grant (DAK) is a fund sourced from revenue in the Central Budget (APBN) allocated to a certain region with the aim of funding special activities of the region in accordance with national priorities. The DAK allocation has a formula component that takes into account the fiscal gap and has a 10 percent matching requirement. The DAK is earmarked for capital spending and cannot be used for research, training, administration, or official travel.','',45,24),(76,'DAK.HE.CR','Total Specific Allocation Grant for Health (in IDR Billion)','The Specific Allocation Grant (DAK) is a fund sourced from revenue in the Central Budget (APBN) allocated to a certain region with the aim of funding special activities of the region in accordance with national priorities. The DAK allocation has a formula component that takes into account the fiscal gap and has a 10 percent matching requirement. The DAK is earmarked for capital spending and cannot be used for research, training, administration, or official travel.','',45,24),(77,'DAK.HE.RSRV.CR','Total Specific Allocation Grant for Health Sector (Subsect: Recommended Services) (in IDR Billion)','The Specific Allocation Grant (DAK) is a fund sourced from revenue in the Central Budget (APBN) allocated to a certain region with the aim of funding special activities of the region in accordance with national priorities. The DAK allocation has a formula component that takes into account the fiscal gap and has a 10 percent matching requirement. The DAK is earmarked for capital spending and cannot be used for research, training, administration, or official travel.','',45,24),(78,'DT.ODA.ALLD.HIV.CNTRL.CD','ODA aid disbursements for STD control including HIV/AIDS, all donors (current US$)','All activities related to sexually transmitted diseases and HIV/AIDS control e.g. information, education and communication; testing; prevention; treatment, care.  Note: data for Sub-Saharan Africa include \"South of Sahara regional\".  Detailed descriptions are available www.oecd.org/dac/stats/crs/directives.  ','',11,24),(79,'DT.ODA.ALLD.HIV.MITI.CD','ODA aid disbursements for Social mitigation of HIV/AIDS, all donors (current US$)','Special programmes to address the consequences of HIV/AIDS, e.g. social, legal and economic assistance to people living with HIV/AIDS including food security and employment; support to vulnerable groups and children orphaned by HIV/AIDS; human rights of HIV/AIDS affected people. Note: data for Sub-Saharan Africa include \"South of Sahara regional\".  Detailed descriptions are available www.oecd.org/dac/stats/crs/directives.  ','',11,24),(80,'DT.ODA.DACD.HIV.CNTRL.CD','ODA aid disbursements for STD control including HIV/AIDS, DAC donors (current US$)','All activities related to sexually transmitted diseases and HIV/AIDS control e.g. information, education and communication; testing; prevention; treatment, care.  Note: data for Sub-Saharan Africa include \"South of Sahara regional\".  Detailed descriptions are available www.oecd.org/dac/stats/crs/directives.  ','',11,3),(81,'DT.ODA.DACD.HIV.MITI.CD','ODA aid disbursements for Social mitigation of HIV/AIDS, DAC donors (current US$)','Special programmes to address the consequences of HIV/AIDS, e.g. social, legal and economic assistance to people living with HIV/AIDS including food security and employment; support to vulnerable groups and children orphaned by HIV/AIDS; human rights of HIV/AIDS affected people. Note: data for Sub-Saharan Africa include \"South of Sahara regional\".  Detailed descriptions are available www.oecd.org/dac/stats/crs/directives.  ','',11,3),(82,'DT.ODA.DACD.HLTH.BAS.CD','Gross ODA aid disbursement for basic health, DAC donors total (current US$)','This is described as basic health care; basic health infrastructure; basic nutrition; infectious disease control; health education; malaria control; tuberculosis control and health personnel development.  Data are in current U.S. dollars.','',11,24),(83,'DT.ODA.DACD.HLTH.CD','Gross ODA aid disbursement for health, DAC donors total (current US$)','This is the aggregate total for general health (DT.ODA.DACD.HLTH.GEN.CD) and basic health (DT.ODA.DACD.HLTH.BAS.CD).  Data are in current U.S. dollars.','',11,24),(84,'DT.ODA.DACD.HLTH.GEN.CD','Gross ODA aid disbursement for general health, DAC donors total (current US$)','This is described as health policy and administrative management; medical education/training; medical research ad medical services.  Data are in current U.S. dollars.','',11,24),(85,'DT.ODA.DACD.POP.CD','Gross ODA aid disbursement for population programmes and reproductive health, DAC donors total (current US$)','This is described as population policy and administrative management; reproductive health care; family planning; STD control including HIV/AIDS and personnel development for population and reproductive health.  Data are in current U.S. dollars.','',11,24),(86,'DT.ODA.MULTI.HIV.CNTRL.CD','ODA aid disbursements for STD control including HIV/AIDS, Multilateral donors (current US$)','All activities related to sexually transmitted diseases and HIV/AIDS control e.g. information, education and communication; testing; prevention; treatment, care.  Note: data for Sub-Saharan Africa include \"South of Sahara regional\".  Detailed descriptions are available www.oecd.org/dac/stats/crs/directives.  ','',11,3),(87,'DT.ODA.MULTI.HIV.MITI.CD','ODA aid disbursements for Social mitigation of HIV/AIDS, Multilateral donors (current US$)','Special programmes to address the consequences of HIV/AIDS, e.g. social, legal and economic assistance to people living with HIV/AIDS including food security and employment; support to vulnerable groups and children orphaned by HIV/AIDS; human rights of HIV/AIDS affected people. Note: data for Sub-Saharan Africa include \"South of Sahara regional\".  Detailed descri